        seen.add(vertex)
        for neighbor in adj[vertex]:
            if neighbor not in seen:
                if visit(neighbor, vertex):
                    return True
            elif undirected_back_edge(neighbor, parent, seen):
                return True
        return False
    for vertex in adj:
        if vertex not in seen and visit(vertex, None):
